import{_ as o,a as e,b as r}from"./chunks/rtk_holybro_h-rtk-m8p_spec.1RfFdMI0.js";import{_ as s}from"./chunks/rtk_holybro_h-rtk_mount_3.DwLha2Oo.js";import{_ as t,o as i,c as l,al as p}from"./chunks/framework.7vp1BMOE.js";const g=JSON.parse('{"title":"Holybro H-RTK M8P GNSS (Discontinued)","description":"","frontmatter":{},"headers":[],"relativePath":"ko/gps_compass/rtk_gps_holybro_h-rtk-m8p.md","filePath":"ko/gps_compass/rtk_gps_holybro_h-rtk-m8p.md"}'),n={name:"ko/gps_compass/rtk_gps_holybro_h-rtk-m8p.md"};function h(c,a,m,_,d,b){return i(),l("div",null,[...a[0]||(a[0]=[p('<h1 id="holybro-h-rtk-m8p-gnss-discontinued" tabindex="-1">Holybro H-RTK M8P GNSS (Discontinued) <a class="header-anchor" href="#holybro-h-rtk-m8p-gnss-discontinued" aria-label="Permalink to &quot;Holybro H-RTK M8P GNSS (Discontinued)&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This GNSS has been discontinued, and is no longer commercially available. Replaced by <a href="./../gps_compass/rtk_gps_holybro_h-rtk-f9p">Holybro H-RTK F9P GNSS</a>.</p></div><p>The <em>Holybro H-RTK M8P GNSS</em> is an <a href="./../gps_compass/rtk_gps">RTK GNSS module</a> series for the mass market. This family is similar to the <a href="./../gps_compass/rtk_gps_holybro_h-rtk-f9p">H-RTK M9P</a> series but uses the smaller, lighter, and less expensive M8P u-blox RTK GNSS module (which still provides far superior position resolution than previous generations_.</p><p>Holybro H-RTK M8P에는 세 가지 모델이 있으며, 각각 다른 요구 사항을 충족하기 위해 서로 다른 안테나 디자인을 사용합니다. Refer to the <a href="#specification-and-model-comparison">Specification and Model Comparison section</a> for more details.</p><p>RTK를 사용하면 PX4는 일반 GPS에서 제공하는 것 보다 훨씬 더 정확한 센티미터 수준의 정확도로 위치를 파악할 수 있습니다.</p><p><img src="'+o+'" alt="h-rtk_rover"></p><h2 id="구매처" tabindex="-1">구매처 <a class="header-anchor" href="#구매처" aria-label="Permalink to &quot;구매처&quot;">​</a></h2><ul><li>Discontinued.</li></ul><h2 id="설정" tabindex="-1">설정 <a class="header-anchor" href="#설정" aria-label="Permalink to &quot;설정&quot;">​</a></h2><p>RTK setup and use on PX4 via <em>QGroundControl</em> is largely plug and play (see <a href="./../gps_compass/rtk_gps">RTK GPS</a> for more information).</p><h2 id="배선" tabindex="-1">배선 <a class="header-anchor" href="#배선" aria-label="Permalink to &quot;배선&quot;">​</a></h2><p>All H-RTK GNSS models come with a GH 10-pin connector/cable that is compatible with <a href="./../flight_controller/pixhawk4">Pixhawk 4</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The cables/connectors may need to be modified in order to connect to other flight controller boards (see <a href="#pin_map">pin map</a>below).</p></div><h2 id="pin_map" tabindex="-1">Pin Map <a class="header-anchor" href="#pin_map" aria-label="Permalink to &quot;Pin Map {#pin_map}&quot;">​</a></h2><p><img src="'+e+'" alt="h-rtk_rover_pinmap"></p><h2 id="사양-및-모델-비교" tabindex="-1">사양 및 모델 비교 <a class="header-anchor" href="#사양-및-모델-비교" aria-label="Permalink to &quot;사양 및 모델 비교&quot;">​</a></h2><p><img src="'+r+'" alt="h-rtk_spec"></p><h2 id="gps-소품" tabindex="-1">GPS 소품 <a class="header-anchor" href="#gps-소품" aria-label="Permalink to &quot;GPS 소품&quot;">​</a></h2><p><a href="https://holybro.com/collections/gps-accessories" target="_blank" rel="noreferrer">GPS Accessories (Holybro Website)</a></p><p><img src="'+s+'" alt="h-rtk"></p>',20)])])}const P=t(n,[["render",h]]);export{g as __pageData,P as default};
